import * as THREE from 'three';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {Garden,centers,gems,patrols} from './logic.js';
const $=id=>document.getElementById(id),state=new Garden(),keys=new Set(),canvas=$('world');
let renderer,scene,camera,hero,portal,gemModels=[],droneModels=[],yaw=Math.PI+.25,pitch=.58,started=false,drag=null,jump=false,audio,sound=false,noticeTimer,previousMode='ready';
const models={},clock=new THREE.Clock();
function message(text){$('notice').textContent=text;$('notice').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').classList.remove('show'),2600);}
function chime(freq){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.3);}catch{}}
function model(name,x,y,z,height=0){const root=new THREE.Group(),o=models[name].clone(true);root.add(o);const b=new THREE.Box3().setFromObject(o),size=b.getSize(new THREE.Vector3()),c=b.getCenter(new THREE.Vector3());const s=height?height/size.y:1;o.scale.multiplyScalar(s);o.position.add(new THREE.Vector3(-c.x*s,-b.min.y*s,-c.z*s));o.traverse(n=>{if(n.isMesh){n.castShadow=true;n.receiveShadow=true;}});root.position.set(x,y,z);scene.add(root);return root;}
function sync(){const active=state.mode==='playing';document.body.classList.toggle('playing',active);$('pause').disabled=!started;$('pause').textContent=active?'Ⅱ':'▷';$('energy').textContent=`◇ ${state.collected.size} / 6`;$('lives').textContent='♥ '.repeat(state.lives).trim()||'—';$('lives').setAttribute('aria-label',`${state.lives} lives`);$('timer').textContent=`${Math.floor(state.time/60)}:${String(Math.floor(state.time%60)).padStart(2,'0')}`;$('objective').textContent=state.collected.size===6?'PORTAL ACTIVE · RETURN TO THE FAR GARDEN':'FIND ALL SIX CRYSTALS';if(state.mode===previousMode)return;previousMode=state.mode;if(state.mode==='paused'){$('eyebrow').textContent='YOUR GARDEN IS WAITING';$('heading').innerHTML='Take a<br><i>breath.</i>';$('description').textContent='Resume whenever you’re ready.';$('begin').textContent='Resume exploring';}if(state.mode==='won'||state.mode==='lost'){$('eyebrow').textContent=state.mode==='won'?'JOURNEY COMPLETE':'TRY A DIFFERENT ROUTE';$('heading').innerHTML=state.mode==='won'?'Welcome<br><i>home.</i>':'Signal<br><i>lost.</i>';$('description').textContent=state.mode==='won'?`All six crystals recovered in ${state.time.toFixed(1)} seconds.`:'Your explorer ran out of energy. A new journey is waiting.';$('begin').textContent='Play again';}}
function begin(){if(!hero)return;state.start();started=true;keys.clear();jump=false;sync();chime(480);canvas.focus();}
$('begin').onclick=begin;$('pause').onclick=()=>{if(state.mode==='playing')state.pause();else if(state.mode==='paused')state.start();sync();};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));chime(520);};
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(state.mode==='playing')state.pause();else if(state.mode==='paused')state.start();sync();}if(e.code==='KeyR'&&['won','lost'].includes(state.mode))begin();if(e.code==='Space'&&!keys.has('Space'))jump=true;keys.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();jump=false;state.pause();sync();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();state.pause();sync();}});
canvas.tabIndex=0;canvas.oncontextmenu=e=>e.preventDefault();canvas.addEventListener('pointerdown',e=>{if(state.mode==='playing'){drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);}});canvas.addEventListener('pointermove',e=>{if(drag?.id!==e.pointerId)return;yaw-=(e.clientX-drag.x)*.007;pitch=THREE.MathUtils.clamp(pitch+(e.clientY-drag.y)*.004,.25,1.05);drag.x=e.clientX;drag.y=e.clientY;});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);if(b.dataset.key==='Space')jump=true;});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.key));});
async function init(){
 renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;
 scene=new THREE.Scene();scene.background=new THREE.Color('#817c9d');scene.fog=new THREE.Fog('#817c9d',38,100);camera=new THREE.PerspectiveCamera(48,1,.1,150);
 scene.add(new THREE.HemisphereLight('#d1e5ec','#544559',2));const sun=new THREE.DirectionalLight('#ffe1b4',3);sun.position.set(-12,28,-16);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-24,right:24,top:24,bottom:-24,near:1,far:90});sun.target.position.set(7,0,7);scene.add(sun.target);sun.shadow.normalBias=.04;sun.shadow.bias=-.00015;scene.add(sun);
 const loader=new GLTFLoader(),names=['Explorer','Drone','Crystal','Portal','Tree','Rock','Island','Path','Crate','Lamp','Bracken','Bluebell','Bench'];let done=0;
 await Promise.all(names.map(async n=>{models[n]=(await loader.loadAsync(`./models/${n}.glb`)).scene;$('begin').textContent=`Growing your garden… ${Math.round(++done/names.length*100)}%`;}));
 for(const [x,z] of centers){const island=model('Island',x,0,z);const box=new THREE.Box3().setFromObject(island);island.position.y-=box.max.y;for(const dx of [-2.8,2.8]){model('Tree',x+dx,0,z+2.5,3.2);model('Rock',x+dx,0,z+1.5,.65);}model('Bracken',x-3.1,0,z-2,.7);model('Bluebell',x+3.1,0,z-2,.75);model('Lamp',x-2,0,z-3.1,1.2);for(let zz=-3;zz<=3;zz++)for(const xx of [-.5,.5])model('Path',x+xx,.008,z+zz,.08);}
 for(let i=4;i<=10;i++)for(const side of [0,14])for(const lane of [-.5,.5]){model('Path',i,-.23,side+lane);model('Path',side+lane,-.23,i);}
 model('Portal',14,0,16,3);portal=model('Crystal',14,.7,16,1.4);portal.visible=false;model('Bench',11.5,0,12,1);model('Crate',-2,0,-2,.75);
 gemModels=gems.map(([x,z])=>model('Crystal',x,.2,z,.95));droneModels=patrols(0).map(([x,z])=>model('Drone',x,1,z,.65));hero=model('Explorer',0,0,-2,1.65);hero.rotation.y=Math.PI;
 $('begin').disabled=false;$('begin').textContent='Begin exploring';
 const context=document.modelContext;if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'read_garden_state',description:'Read the current Crystal Garden game status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No arguments accepted');return state.snapshot();}})).catch(()=>{});}catch{}}
 resize();renderer.setAnimationLoop(frame);
}
function resize(){if(!renderer)return;renderer.setSize(innerWidth,innerHeight,false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}window.addEventListener('resize',resize);
function frame(){const dt=Math.min(clock.getDelta(),.05),moveX=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),moveZ=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),dx=-Math.sin(yaw)*moveZ+Math.cos(yaw)*moveX,dz=-Math.cos(yaw)*moveZ-Math.sin(yaw)*moveX;
 state.step(dt,{x:dx,z:dz,jump,run:keys.has('ShiftLeft')||keys.has('ShiftRight')});jump=false;
 hero.position.set(state.x,state.y+(state.mode==='playing'&&(moveX||moveZ)&&state.y===0?Math.sin(state.time*16)*.035:0),state.z);if(state.mode==='playing'&&(dx||dz)){const angle=Math.atan2(dx,dz);hero.rotation.y+=Math.atan2(Math.sin(angle-hero.rotation.y),Math.cos(angle-hero.rotation.y))*Math.min(1,dt*12);}hero.visible=!(state.time<state.hurtUntil&&Math.floor(state.time*9)%2===0);
 gemModels.forEach((m,i)=>{m.visible=!state.collected.has(i);m.rotation.y=state.time*1.1;m.position.y=.2+Math.sin(state.time*2+i)*.13;});patrols(state.time).forEach(([x,z],i)=>{droneModels[i].position.set(x,1+Math.sin(state.time*3+i)*.12,z);});portal.visible=state.collected.size===6;portal.rotation.y=state.time;
 for(const event of state.events){if(event==='gem'){chime(650+state.collected.size*100);message(state.collected.size===6?'Portal activated! Find your way home.':`${state.collected.size} of 6 crystals recovered`);}if(event==='hurt'){chime(110);message('Energy lost. Returned to the starting garden.');}if(event==='win')chime(1200);}
 const target=started?new THREE.Vector3(state.x,state.y+1,state.z):new THREE.Vector3(6,0,7);const distance=started?9:35;const desired=target.clone().add(new THREE.Vector3(Math.sin(yaw)*Math.cos(pitch)*distance,Math.sin(pitch)*distance,Math.cos(yaw)*Math.cos(pitch)*distance));camera.position.lerp(desired,started?1-Math.exp(-8*dt):1);camera.lookAt(target);sync();renderer.render(scene,camera);
}
init().catch(e=>{console.error(e);$('eyebrow').textContent='GARDEN COULD NOT LOAD';$('heading').innerHTML='Let’s try<br><i>again.</i>';$('description').textContent='Check your connection and use a browser with WebGL enabled.';$('begin').textContent='Reload garden';$('begin').disabled=false;$('begin').onclick=()=>location.reload();});
